  ('islamic-grade1', 'nasr:choose-command', 25, array['islamic_grade1', 'topic_nasr', 'kind_pick'], array['nasr', 'format_choose', 'overall_meaning']),
  ('islamic-grade1', 'nasr:choose-glad-tidings', 25, array['islamic_grade1', 'topic_nasr', 'kind_pick'], array['nasr', 'format_choose', 'occasion']),
  ('islamic-grade1', 'nasr:choose-dhikr', 10, array['islamic_grade1', 'topic_nasr', 'kind_pick'], array['nasr', 'format_choose', 'value']),
  ('islamic-grade1', 'nasr:tf-madani', 15, array['islamic_grade1', 'topic_nasr', 'kind_pick'], array['nasr', 'format_tf', 'surah_type']),
  ('islamic-grade1', 'nasr:tf-makki', 20, array['islamic_grade1', 'topic_nasr', 'kind_pick'], array['nasr', 'format_tf', 'surah_type']),
  ('islamic-grade1', 'nasr:tf-three', 10, array['islamic_grade1', 'topic_nasr', 'kind_pick'], array['nasr', 'format_tf', 'verse_count']),
  ('islamic-grade1', 'nasr:tf-afwaj', 20, array['islamic_grade1', 'topic_nasr', 'kind_pick'], array['nasr', 'format_tf', 'word_meaning']),
  ('islamic-grade1', 'nasr:letter-kha', 15, array['islamic_grade1', 'topic_nasr', 'kind_pick'], array['nasr', 'format_letter', 'tajweed_letter']),
  ('islamic-grade1', 'nasr:letter-kha-word', 20, array['islamic_grade1', 'topic_nasr', 'kind_pick'], array['nasr', 'format_letter', 'tajweed_letter'])
on conflict (quiz_id, question_key) do update set
  difficulty = excluded.difficulty,
  topic_tags = excluded.topic_tags,
  skill_tags = excluded.skill_tags,
  updated_at = now();

do $$
begin
  if (select count(*) from public.question_difficulty_profiles where quiz_id = 'islamic-grade1') <> 119 then
    raise exception 'islamic-grade1 profile count must be exactly 119';
  end if;
end
$$;

commit;

select
  quiz_id,
  count(*) as seeded_questions,
  min(difficulty) as min_difficulty,
  max(difficulty) as max_difficulty
from public.question_difficulty_profiles
where quiz_id = 'islamic-grade1'
group by quiz_id;
